"""wordfreq: print the N most common words from a text file or stdin."""

import argparse
import re
import sys
from collections import Counter

_WORD_RE = re.compile(r"[a-zA-Z]+(?:'[a-zA-Z]+)?")


def tokenize(text, ignore_case=False):
    words = _WORD_RE.findall(text)
    if ignore_case:
        words = [w.lower() for w in words]
    return words


def word_frequencies(text, ignore_case=False, min_length=1):
    counts = Counter(tokenize(text, ignore_case))
    return {w: c for w, c in counts.items() if len(w) >= min_length}


def most_common(freqs, top):
    return Counter(freqs).most_common(top)


def build_parser():
    parser = argparse.ArgumentParser(
        prog="wordfreq",
        description="Print the N most common words in a text file or stdin.",
    )
    parser.add_argument("files", nargs="*", help="text files to read (default: stdin)")
    parser.add_argument("--top", type=int, default=10, metavar="N",
                        help="number of most common words to print (default: 10)")
    parser.add_argument("--ignore-case", action="store_true",
                        help="treat 'Word' and 'word' as the same word")
    parser.add_argument("--min-length", type=int, default=1, metavar="N",
                        help="ignore words shorter than N characters (default: 1)")
    return parser


def main(argv=None):
    args = build_parser().parse_args(argv)

    if args.files:
        chunks = []
        for path in args.files:
            with open(path, encoding="utf-8") as fh:
                chunks.append(fh.read())
        text = "\n".join(chunks)
    else:
        text = sys.stdin.read()

    freqs = word_frequencies(text, args.ignore_case, args.min_length)
    for word, count in most_common(freqs, args.top):
        print(f"{word}\t{count}")


if __name__ == "__main__":
    main()
